<script setup lang="ts">
import InputText from 'primevue/inputtext'
import InputNumber from 'primevue/inputnumber'
import Select from 'primevue/select'
import {finishLabels} from '../services/types'
import type {PaintFinish} from '../services/types'
import FileUpload from 'primevue/fileupload'
import Button from 'primevue/button'

import { reactive,ref,watch } from 'vue'
import Dialog from 'primevue/dialog'
import { useToast } from 'primevue/usetoast'
import { useGarage } from '../stores/garage'
import { api } from '../services/api'
import type { Vehicle } from '../services/types'
const visible=defineModel<boolean>('visible',{default:false}),props=defineProps<{vehicle?:Vehicle|null}>()
const g=useGarage(),toast=useToast(),busy=ref(false),error=ref(''),savedId=ref<string|null>(null),photo=ref<File|null>(null)
const form=reactive({manufacturer:'',model:'',manufactureYear:new Date().getFullYear(),modelYear:new Date().getFullYear(),version:'',color:'',colorHex:null as string|null,paintFinish:null as PaintFinish|null,mileage:null as number|null,nickname:'',plate:''})
watch(visible,v=>{if(!v)return;savedId.value=props.vehicle?.id??null;photo.value=null;error.value='';Object.assign(form,props.vehicle??{manufacturer:'',model:'',manufactureYear:new Date().getFullYear(),modelYear:new Date().getFullYear(),version:'',color:'',colorHex:null as string|null,paintFinish:null as PaintFinish|null,mileage:null,nickname:'',plate:''})})
async function save(){busy.value=true;error.value='';try{const v=await api<Vehicle>('/vehicles'+(savedId.value?'/'+savedId.value:''),{method:savedId.value?'PUT':'POST',body:JSON.stringify({...form,colorHex:form.colorHex||null,mileage:form.mileage==null||String(form.mileage)===''?null:Number(form.mileage)})});savedId.value=v.id;if(photo.value){const body=new FormData();body.append('file',photo.value);await api(`/vehicles/${v.id}/photo`,{method:'POST',body})}g.selectedId=v.id;await g.loadVehicles();visible.value=false;toast.add({severity:'success',summary:'Veículo salvo',life:3000})}catch(e){error.value=(savedId.value?'O veículo está salvo. ':'')+(e as Error).message;await g.loadVehicles()}finally{busy.value=false}}
</script>
<template><Dialog v-model:visible="visible" modal :header="savedId?'Editar veículo':'Adicionar veículo'" :style="{width:'640px'}" :breakpoints="{'700px':'95vw'}"><form class="form-grid" @submit.prevent="save"><label for="vehicle-manufacturer">Fabricante<InputText id="vehicle-manufacturer" v-model="form.manufacturer" required maxlength="80" /></label><label for="vehicle-model">Modelo<InputText id="vehicle-model" v-model="form.model" required maxlength="100" /></label><label for="vehicle-manufactureYear">Ano de fabricação<InputNumber input-id="vehicle-manufactureYear" v-model="form.manufactureYear" :min="1900" :max="new Date().getFullYear()+1" :use-grouping="false" required /></label><label for="vehicle-modelYear">Ano do modelo<InputNumber input-id="vehicle-modelYear" v-model="form.modelYear" :min="1900" :max="new Date().getFullYear()+1" :use-grouping="false" required /></label><label for="vehicle-version">Versão<InputText id="vehicle-version" v-model="form.version" maxlength="120" /></label><label for="vehicle-color">Cor<InputText id="vehicle-color" v-model="form.color" maxlength="80" /></label><label for="vehicle-hex">Cor hexadecimal (opcional)<InputText id="vehicle-hex" v-model="form.colorHex" maxlength="7" pattern="#[0-9a-fA-F]{6}" placeholder="#C0C0C0" /></label><label for="vehicle-finish">Acabamento<Select input-id="vehicle-finish" aria-label="Acabamento" v-model="form.paintFinish" :options="Object.entries(finishLabels).map(([value,label])=>({value,label}))" option-label="label" option-value="value" show-clear placeholder="Não informado" /></label><label for="vehicle-mileage">Quilometragem atual<InputNumber input-id="vehicle-mileage" v-model="form.mileage" :min="vehicle?.mileage??0" :max="10000000" :use-grouping="false" placeholder="Não informada" /></label><label for="vehicle-nickname">Apelido<InputText id="vehicle-nickname" v-model="form.nickname" maxlength="80" /></label><label for="vehicle-plate">Placa (opcional)<InputText id="vehicle-plate" v-model="form.plate" maxlength="12" /></label><label>Foto<FileUpload mode="basic" name="photo" accept="image/png,image/jpeg,image/webp" :max-file-size="8388608" custom-upload choose-label="Selecionar foto" @select="photo=$event.files[0]??null" /></label><p class="full muted">Preencha apenas as informações que conhece. A quilometragem não pode diminuir depois de registrada.</p><p v-if="error" class="full form-error" role="alert">{{error}}</p><div class="full form-actions"><Button type="button" class="button" @click="visible=false">Cancelar</Button><Button type="submit" class="button primary" :disabled="busy">{{busy?'Salvando…':'Salvar veículo'}}</Button></div></form></Dialog></template>
